local K={61,67,3,103,79,23,125,185,169,77,138,199,166,214,230,217,177,132,151,123,4,217,213,11}
local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local M={}
for i=1,64 do M[string.byte(A,i)]=i-1 end
local D=[==[



























































































































































































































































































































































































































































































































































































































































































































































































































































































































































































]==]
D=D:gsub("%s","")
local X=bit32 and bit32.bxor or function(a,b)local r,p=0,1 while a>0 or b>0 do local x,y=a%2,b%2 if x~=y then r=r+p end a=(a-x)/2 b=(b-y)/2 p=p*2 end return r end
local n,kl,o,oc=0,#K,{},0
local ch=char or string.char
for s=1,#D,4000 do
local t={D:byte(s,math.min(s+3999,#D))}
local r,rc={},0
for j=1,#t,4 do
local a,b,c,d=M[t[j]],M[t[j+1]],M[t[j+2]],M[t[j+3]]
local v=a*262144+b*4096+c*64+d
local x,y,z=math.floor(v/65536),math.floor(v/256)%256,v%256
r[rc+1]=ch(X(x,K[n%kl+1]),X(y,K[(n+1)%kl+1]),X(z,K[(n+2)%kl+1]))
rc=rc+1 n=n+3
end
oc=oc+1 o[oc]=table.concat(r)
end
local src=table.concat(o)
local f,loaderr=(loadstring or load)(src)
if not f then
	warn("[null-obf] DECODE/COMPILE FAILED: "..tostring(loaderr))
	warn("[null-obf] decoded length was: "..#src)
	warn("[null-obf] first 80 chars of decoded: "..src:sub(1,80))
	warn("[null-obf] last 80 chars of decoded: "..src:sub(-80))
	return nil
end
return f(...)
